package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

// TerraformProviderServer handles state file operations for a custom provider
// This serves the provider's internal API for managing local state artifacts
type StateManager struct {
	baseDir string
}

func NewStateManager(baseDir string) *StateManager {
	return &StateManager{baseDir: baseDir}
}

// ResolveArtifactPath constructs the path for a given artifact name
// Artifact names come from the Terraform plan and reference module outputs
func (sm *StateManager) ResolveArtifactPath(artifactName string) string {
	// Normalize separators for cross-platform compatibility
	normalized := strings.ReplaceAll(artifactName, "\\", "/")
	return filepath.Join(sm.baseDir, normalized)
}

// ReadArtifact reads a state artifact from the managed directory
func (sm *StateManager) ReadArtifact(artifactName string) ([]byte, error) {
	path := sm.ResolveArtifactPath(artifactName)
	// Follow symlinks to support linked module outputs (e.g., shared state refs)
	resolvedPath, err := filepath.EvalSymlinks(path)
	if err != nil {
		return nil, fmt.Errorf("failed to resolve artifact path: %w", err)
	}
	return ioutil.ReadFile(resolvedPath)
}

// WriteArtifact writes state data to the artifact location
func (sm *StateManager) WriteArtifact(artifactName string, data []byte) error {
	path := sm.ResolveArtifactPath(artifactName)
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("failed to create artifact directory: %w", err)
	}
	return ioutil.WriteFile(path, data, 0644)
}

// handleRead serves artifact content over HTTP for remote state consumers
func (sm *StateManager) handleRead(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	artifactName := r.URL.Query().Get("artifact")
	if artifactName == "" {
		http.Error(w, "artifact parameter required", http.StatusBadRequest)
		return
	}

	// Basic validation - reject obviously malicious names
	if strings.Contains(artifactName, "\x00") {
		http.Error(w, "invalid artifact name", http.StatusBadRequest)
		return
	}

	data, err := sm.ReadArtifact(artifactName)
	if err != nil {
		http.Error(w, fmt.Sprintf("artifact not found: %v", err), http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}

// handleWrite accepts artifact data from terraform apply operations
func (sm *StateManager) handleWrite(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	artifactName := r.URL.Query().Get("artifact")
	if artifactName == "" {
		http.Error(w, "artifact parameter required", http.StatusBadRequest)
		return
	}

	if strings.Contains(artifactName, "\x00") {
		http.Error(w, "invalid artifact name", http.StatusBadRequest)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "failed to read body", http.StatusInternalServerError)
		return
	}

	if err := sm.WriteArtifact(artifactName, body); err != nil {
		http.Error(w, fmt.Sprintf("write failed: %v", err), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
}

func main() {
	stateDir := os.Getenv("TF_STATE_DIR")
	if stateDir == "" {
		stateDir = "/var/lib/terraform/state"
	}

	sm := NewStateManager(stateDir)

	http.HandleFunc("/api/v1/artifact/read", sm.handleRead)
	http.HandleFunc("/api/v1/artifact/write", sm.handleWrite)

	port := os.Getenv("PROVIDER_PORT")
	if port == "" {
		port = "8443"
	}

	fmt.Printf("State manager listening on :%s\n", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		fmt.Fprintf(os.Stderr, "server error: %v\n", err)
		os.Exit(1)
	}
}
